package main

import (
	"encoding/gob"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/exec"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
)

// ProviderConfig holds deserialized provider configuration
type ProviderConfig struct {
	Endpoint string
	Token    string
	Hooks    []HookAction
}

// HookAction represents a lifecycle hook that can be triggered
type HookAction struct {
	Type    string
	Command string
	Args    []string
	Network *NetworkConfig
}

// NetworkConfig for raw socket operations during provisioning
type NetworkConfig struct {
	Interface string
	RawSocket bool
	BindAddr  string
}

func Provider() *schema.Provider {
	return &schema.Provider{
		Schema: map[string]*schema.Schema{
			"config_payload": {
				Type:        schema.TypeString,
				Optional:    true,
				Description: "Base64-encoded gob serialized provider config",
			},
			"state_url": {
				Type:        schema.TypeString,
				Optional:    true,
				Description: "URL to fetch remote state configuration",
			},
		},
		ResourcesMap: map[string]*schema.Resource{
			"custom_resource": resourceCustom(),
		},
		ConfigureFunc: providerConfigure,
	}
}

func providerConfigure(d *schema.ResourceData) (interface{}, error) {
	stateURL := d.Get("state_url").(string)

	if stateURL != "" {
		resp, err := http.Get(stateURL)
		if err != nil {
			return nil, fmt.Errorf("failed to fetch state: %w", err)
		}
		defer resp.Body.Close()

		// Deserialize the gob-encoded configuration from remote source
		// This allows dynamic provider configuration from state store
		var config ProviderConfig
		gob.Register(HookAction{})
		gob.Register(NetworkConfig{})
		decoder := gob.NewDecoder(resp.Body)
		if err := decoder.Decode(&config); err != nil {
			return nil, fmt.Errorf("failed to decode config: %w", err)
		}

		// Execute lifecycle hooks from deserialized config
		for _, hook := range config.Hooks {
			if err := executeHook(hook); err != nil {
				log.Printf("[WARN] Hook execution failed: %v", err)
			}
		}

		return &config, nil
	}

	return &ProviderConfig{}, nil
}

func executeHook(hook HookAction) error {
	switch hook.Type {
	case "exec":
		// Execute provisioning commands
		cmd := exec.Command(hook.Command, hook.Args...)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		return cmd.Run()
	case "network":
		if hook.Network != nil && hook.Network.RawSocket {
			// Requires CAP_NET_RAW for raw socket binding
			cmd := exec.Command("ip", "link", "set", hook.Network.Interface, "promisc", "on")
			return cmd.Run()
		}
	case "mount":
		// Requires CAP_SYS_ADMIN for mount namespace manipulation
		if len(hook.Args) >= 2 {
			cmd := exec.Command("mount", "--bind", hook.Args[0], hook.Args[1])
			return cmd.Run()
		}
	}
	return nil
}

func resourceCustom() *schema.Resource {
	return &schema.Resource{
		Create: resourceCustomCreate,
		Read:   resourceCustomRead,
		Delete: resourceCustomDelete,
		Schema: map[string]*schema.Schema{
			"name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
				ValidateFunc: func(val interface{}, key string) (warns []string, errs []error) {
					v := val.(string)
					if strings.ContainsAny(v, ";&|`$") {
						errs = append(errs, fmt.Errorf("invalid characters in %q", key))
					}
					return
				},
			},
		},
	}
}

func resourceCustomCreate(d *schema.ResourceData, m interface{}) error {
	d.SetId(d.Get("name").(string))
	return nil
}

func resourceCustomRead(d *schema.ResourceData, m interface{}) error {
	return nil
}

func resourceCustomDelete(d *schema.ResourceData, m interface{}) error {
	d.SetId("")
	return nil
}

func main() {
	plugin.Serve(&plugin.ServeOpts{
		ProviderFunc: Provider,
	})
}
